class NumMatrix:
    def __init__(self, matrix):
        self.m, self.n = len(matrix), len(matrix[0])
        self.tree = [[0] * (self.n + 1) for _ in range(self.m + 1)]
        self.vals = [row[:] for row in matrix]
        for i in range(self.m):
            for j in range(self.n):
                self._add(i + 1, j + 1, matrix[i][j])

    def _add(self, r, c, d):
        i = r
        while i <= self.m:
            j = c
            while j <= self.n:
                self.tree[i][j] += d
                j += j & (-j)
            i += i & (-i)

    def _prefix(self, r, c):
        s, i = 0, r
        while i > 0:
            j = c
            while j > 0:
                s += self.tree[i][j]
                j -= j & (-j)
            i -= i & (-i)
        return s

    def update(self, row, col, val):
        self._add(row + 1, col + 1, val - self.vals[row][col])
        self.vals[row][col] = val

    def sumRegion(self, row1, col1, row2, col2):
        return (self._prefix(row2 + 1, col2 + 1) - self._prefix(row1, col2 + 1)
                - self._prefix(row2 + 1, col1) + self._prefix(row1, col1))

