class NumMatrix {
public:
    int m, n;
    vector<vector<int>> tree, vals;
    NumMatrix(vector<vector<int>>& matrix) {
        m = matrix.size(); n = matrix[0].size();
        tree.assign(m + 1, vector<int>(n + 1, 0));
        vals = matrix;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) add(i + 1, j + 1, matrix[i][j]);
    }
    void add(int r, int c, int d) {
        for (int i = r; i <= m; i += i & (-i))
            for (int j = c; j <= n; j += j & (-j)) tree[i][j] += d;
    }
    long long prefix(int r, int c) {
        long long s = 0;
        for (int i = r; i > 0; i -= i & (-i))
            for (int j = c; j > 0; j -= j & (-j)) s += tree[i][j];
        return s;
    }
    void update(int row, int col, int val) {
        add(row + 1, col + 1, val - vals[row][col]);
        vals[row][col] = val;
    }
    int sumRegion(int row1, int col1, int row2, int col2) {
        return prefix(row2 + 1, col2 + 1) - prefix(row1, col2 + 1)
             - prefix(row2 + 1, col1) + prefix(row1, col1);
    }
};

