class NumMatrix {
    private int m, n;
    private int[][] tree, vals;
    public NumMatrix(int[][] matrix) {
        m = matrix.length; n = matrix[0].length;
        tree = new int[m + 1][n + 1];
        vals = new int[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) { vals[i][j] = matrix[i][j]; add(i + 1, j + 1, matrix[i][j]); }
    }
    private void add(int r, int c, int d) {
        for (int i = r; i <= m; i += i & (-i))
            for (int j = c; j <= n; j += j & (-j)) tree[i][j] += d;
    }
    private long prefix(int r, int c) {
        long s = 0;
        for (int i = r; i > 0; i -= i & (-i))
            for (int j = c; j > 0; j -= j & (-j)) s += tree[i][j];
        return s;
    }
    public void update(int row, int col, int val) {
        add(row + 1, col + 1, val - vals[row][col]);
        vals[row][col] = val;
    }
    public int sumRegion(int row1, int col1, int row2, int col2) {
        return (int)(prefix(row2 + 1, col2 + 1) - prefix(row1, col2 + 1)
                   - prefix(row2 + 1, col1) + prefix(row1, col1));
    }
}

